<?php $e = static fn (mixed $v): string => htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); ?>
<div class="space-y-6"><div><h1 class="text-2xl font-bold">Разрешения</h1><p class="text-sm text-slate-500">Разрешенията се управляват от permission registry и се задават чрез роли.</p></div><div class="overflow-hidden rounded-xl border bg-white dark:border-slate-700 dark:bg-slate-800"><table class="w-full text-left text-sm"><thead><tr><th class="p-4">Ключ</th><th class="p-4">Име</th><th class="p-4">Модул</th><th class="p-4">Роли</th></tr></thead><tbody><?php foreach ($permissions as $permission): ?><tr class="border-t dark:border-slate-700"><td class="p-4"><code><?= $e($permission->slug) ?></code></td><td class="p-4"><?= $e($permission->name) ?></td><td class="p-4"><?= $e($permission->module) ?></td><td class="p-4"><?= (int) $permission->roles_count ?></td></tr><?php endforeach; ?></tbody></table></div></div>
